package com.spidergram.app;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;
public class MainActivity extends Activity{WebView web;public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient());web.loadUrl("https://spidergram-production.up.railway.app/");}public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}}
